	private static final class LeftKeys implements RowCursor {
		private final RowState row;
		private final long[] values;
		private int index;

		private LeftKeys(RowState row, long[] values) {
			this.row = row;
			this.values = values;
		}

		@Override
		public boolean next() {
			if (index == values.length) {
				return false;
			}
			row.slots[0] = values[index++];
			row.slots[1] = UNKNOWN;
			row.recomputeBoundMask();
			return true;
		}

		@Override
		public void close() {
			index = values.length;
		}
	}

